  name = 'Chanel',
  origin_location = 'Paris, France',
  origin_meaning = 'Coco Chanel''s birth name was Gabrielle Bonheur Chanel. ''Coco'' was her cabaret stage name, forever tied to revolutionary style.',
  known_for_tags = '[{"name": "Effortless", "description": ""}, {"name": "Tweed tailoring", "description": ""}, {"name": "Pearls", "description": ""}, {"name": "Black & white", "description": ""}, {"name": "Parisian ease", "description": ""}]',
  founder = 'Gabrielle ''Coco'' Chanel',
  signature_pieces = '[{"name": "Classic 11.12 Handbag", "image_url": "https://static.wixstatic.com/media/2d21ff_97cc88ee67f049db84e92e008b593c49~mv2.webp/v1/fill/w_1056,h_1234/79786313.webp", "link": "https://www.chanel.com/il-en/fashion/p/A01112B23528NAFRR/classic-11-12-handbag-cotton-tweed-gold-tone-metal/"}, {"name": "Wool Tweed Jacket", "image_url": "https://static.wixstatic.com/media/2d21ff_f2c4a4268b5f4d9cbb07bed84afdd691~mv2.webp/v1/fill/w_1760,h_2644/80383234.webp", "link": "https://www.chanel.com/il-en/fashion/p/P81166V67582M9999/jacket-wool-tweed/"}, {"name": "Chanel Pearl Necklace", "image_url": "https://static.wixstatic.com/media/2d21ff_f9a7ba5f54b54e8a90c6c52d0420b416~mv2.webp/v1/fill/w_1210,h_1412/79478815.webp", "link": "https://www.chanel.com/il-en/fashion/p/ABH257B23664U8018/long-necklace-metal-glass-pearls-diamantes/"}]',
  eras = '[{"title": "Coco''s Revolution", "year_range": "1910 – 1971", "description": "Gabrielle ''Coco'' Chanel liberated women from corsets, introducing jersey fabrics, the little black dress, and timeless pieces that prioritized comfort and elegance. Her vision of effortless chic redefined modern femininity.", "images": ["https://static.wixstatic.com/media/2d21ff_7b20bd64c8da4f0191d0a61948345937~mv2.webp/v1/fill/w_683,h_1024/chanel_12.webp", "https://static.wixstatic.com/media/2d21ff_7d57c62509284c4c8c094345507d180f~mv2.jpg/v1/fill/w_499,h_843/348b1d9fd1eb89f7095e0698d26c7fa4.jpg", "https://static.wixstatic.com/media/2d21ff_582f1d1e37d54b658737686e10669d73~mv2.png/v1/fill/w_1230,h_1600/image-7.png", "https://static.wixstatic.com/media/2d21ff_cc8a7a7518c4448e92aded4d1f86d7bb~mv2.jpg/v1/fill/w_1440,h_1920/f.elconfidencial.com_original_fe0_f09_de5_fe0f09de517fdd538abc1b1213f26262.jpg", "https://static.wixstatic.com/media/2d21ff_5785e9375df24a41aec47e2dc22f2a9c~mv2.webp/v1/fill/w_1000,h_1600/coco-chanel-designs-263284-1531910448870-image-1000-80.jpg.webp", "https://static.wixstatic.com/media/2d21ff_60520ff70a6e44b1ad3829328f89ba14~mv2.webp/v1/fill/w_1000,h_1600/coco-chanel-designs-263284-1531910452866-image-1000-80.jpg.webp", "https://static.wixstatic.com/media/2d21ff_876c020ec024430fb6f04451d3ba4963~mv2.webp/v1/fill/w_1000,h_1600/coco-chanel-designs-263284-1531910461729-image-1000-80.jpg.webp", "https://static.wixstatic.com/media/2d21ff_cbed1920efa24199b2bf7dd788cdf083~mv2.webp/v1/fill/w_1600,h_1600/proof-that-coco-chanels-designs-are-relevant-as-ever-2884798-1600-80.jpg.webp", "https://static.wixstatic.com/media/2d21ff_eb21670ef3d94e379d1b3387cbfb0aad~mv2.webp/v1/fill/w_1600,h_2132/proof-that-coco-chanels-designs-are-relevant-as-ever-2884801-1600-80.jpg.webp", "https://static.wixstatic.com/media/2d21ff_41da50b42004404a8e04014d709595de~mv2.jpg/v1/fill/w_1900,h_2350/proof-that-coco-chanels-designs-are-relevant-as-ever-2884805.jpg"]}, {"title": "Karl''s Revival", "year_range": "1983 – 2004", "description": "Karl Lagerfeld breathed new life into the house, reinterpreting Coco''s codes with irreverence and glamour. Bold logos, iconic handbags, and supermodel-led campaigns made Chanel a global powerhouse.", "images": ["https://static.wixstatic.com/media/2d21ff_f05c1b425b994603bb753404ff3fa97f~mv2.webp/v1/fill/w_1004,h_1514/chanels-1992-chain-dress-v0-xybi8dy3tbsa1.webp", "https://static.wixstatic.com/media/2d21ff_c08d5971168e48888fec74ea76ca741f~mv2.jpg/v1/fill/w_768,h_1160/0cf6eef6db43af00e5b9f3b4f36adab1_master.jpg", "https://static.wixstatic.com/media/2d21ff_87fd0a7f896b4b37a8abf7dca01990ab~mv2.webp/v1/fill/w_2008,h_3035/014-chanel-fall-1995-couture-CN10008099-kate-moss.webp", "https://static.wixstatic.com/media/2d21ff_f1131adbfe6148be8d969db4d803af89~mv2.jpg/v1/fill/w_735,h_1107/1cc86dbf0a7350dc32fd4687ead6197e.jpg", "https://static.wixstatic.com/media/2d21ff_212b27d7ae74451ab6f018f989e68d7b~mv2.webp/v1/fill/w_2096,h_3205/004-chanel-fall-1995-couture-detail-CN10059824-nadja-auermann.webp", "https://static.wixstatic.com/media/2d21ff_641d6b8cf32747bd86980dd7853deb81~mv2.jpg/v1/fill/w_3942,h_5776/GettyImages-502741540.jpg", "https://static.wixstatic.com/media/2d21ff_f05c1b425b994603bb753404ff3fa97f~mv2.webp/v1/fill/w_1004,h_1514/chanels-1992-chain-dress-v0-xybi8dy3tbsa1.webp", "https://static.wixstatic.com/media/2d21ff_4d1a5233e1f94f38bb3fb0b78e7ff420~mv2.jpg/v1/fill/w_800,h_1199/1667384-800w.jpg", "https://static.wixstatic.com/media/2d21ff_955e377ad9d143549e782ad08c62a497~mv2.webp/v1/fill/w_2400,h_3600/001-chanel-spring-1995-ready-to-wear-details-CN10011218-claudia-schiffer.webp"]}, {"title": "Karl''s Spectacle Era", "year_range": "2005 – 2019", "description": "Lagerfeld transformed fashion shows into theatrical events—building rocket ships, recreating streets, and turning runways into art installations. Chanel became synonymous with fantasy and spectacle.", "images": ["https://static.wixstatic.com/media/2d21ff_a0934a8bdb7e442095e8227844af2a13~mv2.jpg/v1/fill/w_1920,h_2877/chanel-fall-2005-couture-00500h-solange-wilvert.jpg", "https://static.wixstatic.com/media/2d21ff_bbe7b3f61e074f91b87ad7c92d82c3a8~mv2.webp/v1/fill/w_683,h_1024/chanel-006.webp", "https://static.wixstatic.com/media/2d21ff_f326098197b04d44bf3212227b752dfc~mv2.webp/v1/fill/w_683,h_1026/chanel-couture-spring-2017-collection-72.webp", "https://static.wixstatic.com/media/2d21ff_757ed40f41a54987ba5d34cecc5f67a3~mv2.jpg/v1/fill/w_320,h_480/chanelcouture62.jpg", "https://static.wixstatic.com/media/2d21ff_309931bfb25f4660b953291a9c8cd253~mv2.webp/v1/fill/w_640,h_967/chanel-haute-couture-ss-2005-1023x1546-v0-4ui3sucbkz3b1.webp", "https://static.wixstatic.com/media/2d21ff_1ea3d856c7f9430384eab1b886fa8549~mv2.jpg/v1/fill/w_800,h_1181/chanel-spring-summer-2013-womenswear-collection-01.jpg", "https://static.wixstatic.com/media/2d21ff_e47c8fb7588e4319b149db10c1860a4c~mv2.jpg/v1/fill/w_240,h_362/86786208-chanel-spring-2005.jpg", "https://static.wixstatic.com/media/2d21ff_a21fc24739b2414c972e4decec400e03~mv2.jpg/v1/fill/w_800,h_1181/chanel-spring-summer-2013-womenswear-collection-01.jpg", "https://static.wixstatic.com/media/2d21ff_0fea8c60496e4d7785b1c97afc433cc9~mv2.jpg/v1/fill/w_400,h_602/https___prod.static9.net.au___media_Network_Images_2017_01_25_10_23_Roos-Abels.jpg"]}, {"title": "The Blazy Reset", "year_range": "2025 – Present", "description": "Matthieu Blazy brings a quieter confidence to Chanel, stripping away excess and focusing on craft, texture, and modern ease. His approach honors the house codes while making them feel relevant for today.", "images": ["https://static.wixstatic.com/media/2d21ff_98d354fa7146415a9a8b13f85acebf42~mv2.jpg/v1/fill/w_2040,h_3015/chanel-spring-summer-2026-copyright-chanel-look-1-hd.jpg", "https://static.wixstatic.com/media/2d21ff_f460d2e34c734192a7771bfde0c99bf7~mv2.webp/v1/fill/w_1000,h_1500/ISI01882.webp", "https://static.wixstatic.com/media/2d21ff_e173d4af6f9e49f1ac99c4ebdbde58ae~mv2.avif/v1/fill/w_666,h_1000/f21f.avif", "https://static.wixstatic.com/media/2d21ff_319621b480d5421cbdbd082dbcbfbbf3~mv2.jpg/v1/fill/w_1200,h_1774/chanel_mda-2026-copyright-chanel-look_-8-HD.jpg", "https://static.wixstatic.com/media/2d21ff_992299678ae042d9ac16ac0596a11d25~mv2.avif/v1/fill/w_780,h_1170/chanel_metiers-dart-2026_copyright-chanel.avif", "https://static.wixstatic.com/media/2d21ff_66e8b8425f7e4dab83368be549e1b42e~mv2.avif/v1/fill/w_2612,h_3861/chanel-prefall-po-f26-004-693003897d2e8.avif", "https://static.wixstatic.com/media/2d21ff_c443993be23149c4be8c276a86af5469~mv2.webp/v1/fill/w_2560,h_3840/chanel-vogue-business-story.webp", "https://static.wixstatic.com/media/2d21ff_8c0c2e31a7e84ddbb25a6939378e8441~mv2.webp/v1/fill/w_1600,h_2448/chanel-vogue-business-story-inline%20copy.webp", "https://static.wixstatic.com/media/2d21ff_91951c68dffc47a9b1936a54d7a9656b~mv2.webp/v1/fill/w_1600,h_2448/chanel-vogue-business-story-inline%20copy%203.webp"]}]',
  phonetic = 'shuh-NEL',
  creative_director = 'Matthieu Blazy',
