UPDATE designers SET
  name = 'Dior',
  origin_location = 'Paris, France',
  origin_meaning = 'French surname meaning ''golden'' (d''or). Christian Dior''s family name literally translates to ''of gold''.',
  known_for_tags = '[{"name": "The new look", "description": ""}, {"name": "Couture driven", "description": ""}, {"name": "Romantic", "description": ""}, {"name": "Elegant", "description": ""}]',
  founder = 'Christian Dior',
  signature_pieces = '[{"name": "Lady Dior Bag", "image_url": "https://static.wixstatic.com/media/2d21ff_e7c1dc0c67724ff7b26a4485db7fe5f7~mv2.webp/v1/fill/w_1850,h_2000/M0531OUQAM36Z_SBG_E01.webp", "link": "https://www.dior.com/en_int/fashion/products/M0531OUQA_M36Z"}, {"name": "Bar Jacket", "image_url": "https://static.wixstatic.com/media/2d21ff_d7ab7f851ecf4734a8329ca8d5daa88e~mv2.webp/v1/fill/w_1850,h_2000/621V09A1952X8330_SBG_E01.webp", "link": "https://www.dior.com/en_int/fashion/products/621V09A1952_X8330"}, {"name": "Dior Saddle bag", "image_url": "https://static.wixstatic.com/media/2d21ff_da6d17740fae4623b4c40e7d95d7931f~mv2.webp/v1/fill/w_1850,h_2000/M0455CBAAM42R_SBG_E01.webp", "link": "https://www.dior.com/en_int/fashion/products/M0455CBAA_M42R"}, {"name": "Dior Muse Pump", "image_url": "https://static.wixstatic.com/media/2d21ff_2729c009b44041a2805582483084a271~mv2.webp/v1/fill/w_1850,h_2000/KCV500VCRS07X_SBG_E02-3.webp", "link": "https://www.dior.com/en_int/fashion/products/KCV500VCR_S07X"}, {"name": "Belted Pleated Dress", "image_url": "https://static.wixstatic.com/media/2d21ff_8fcd5c59998641ee9d3ee30380f7c1f4~mv2.webp/v1/fill/w_1850,h_2000/621R05A6991X0909_SBG_E01.webp", "link": "https://www.dior.com/en_int/fashion/products/621R05A6991_X0909"}, {"name": "Dior Ballet Flat", "image_url": "https://static.wixstatic.com/media/2d21ff_5a1a37d4b4384697abe5c8ec24a9acb4~mv2.webp/v1/fill/w_1850,h_2000/KCB860CQCS900_SBG_E02-2.webp", "link": "https://www.dior.com/en_int/fashion/products/KCB860CQC_S900"}]',
  eras = '[{"title": "The New Look Revolution", "year_range": "1947 - 1957", "description": "Christian Dior revolutionized post-war fashion with his iconic ''New Look'' in 1947, cinched waists, full skirts, and ultra-feminine silhouettes that rejected wartime austerity. This era established Dior as the epitome of luxury and redefined women''s fashion worldwide.", "images": ["https://static.wixstatic.com/media/2d21ff_37398b1ba77c4cd3837e67c17760c449~mv2.png/v1/fill/w_2560,h_2560/image-30.png", "https://static.wixstatic.com/media/2d21ff_1e3c7a7eb58b4e5d831ae2a2e15fbca4~mv2.webp/v1/fill/w_515,h_712/0407-VO-FB27.03.webp", "https://static.wixstatic.com/media/2d21ff_1e3c7a7eb58b4e5d831ae2a2e15fbca4~mv2.webp/v1/fill/w_515,h_712/0407-VO-FB27.03.webp", "https://static.wixstatic.com/media/2d21ff_bdbdb13abc0843ba89d57f5b68794f16~mv2.jpg/v1/fill/w_599,h_800/diordress.jpg", "https://static.wixstatic.com/media/2d21ff_780675ef088c4da3a50c841d787aec6c~mv2.jpg/v1/fill/w_367,h_550/dress-by-christian-dior-1948-new-look-style_u-l-pwgk4v0.jpg", "https://static.wixstatic.com/media/2d21ff_4137c904997440d38c56cce87d8b7b45~mv2.jpg/v1/fill/w_553,h_844/bb8871e0bc01d74c59f2c4c746b9fdf9.jpg", "https://static.wixstatic.com/media/2d21ff_cf5ca7798cbf424394f1a1412b1f9154~mv2.png/v1/fill/w_389,h_537/1_jHqgHr8bqSt-6AFvEar6ug.png"]}, {"title": "The Galliano Fantasy", "year_range": "1996 - 2011", "description": "John Galliano brought theatrical maximalism to Dior, merging historical references with avant-garde drama. His era was defined by extravagant runway shows, narrative-driven collections, and a celebration of couture craftsmanship pushed to fantastical extremes.", "images": ["https://static.wixstatic.com/media/2d21ff_8c7f91e96f6a4880a833547b0227663b~mv2.jpg/v1/fill/w_2400,h_3600/temp%2047.JPG", "https://static.wixstatic.com/media/2d21ff_f0e9a51546a54a29bc80cd636dd52c8e~mv2.jpg/v1/fill/w_2400,h_3600/temp%2043.JPG", "https://static.wixstatic.com/media/2d21ff_cb4df031a9ae4782802753d51ddcc7b1~mv2.jpg/v1/fill/w_2400,h_3600/temp%2046.JPG", "https://static.wixstatic.com/media/2d21ff_76515e56e8a74bc4bd8161cb7218ce00~mv2.jpg/v1/fill/w_2400,h_3600/temp%2044.JPG", "https://static.wixstatic.com/media/2d21ff_32d045b5fe8d4b48801063f5267270d8~mv2.jpg/v1/fill/w_2400,h_3600/temp%2045.JPG", "https://static.wixstatic.com/media/2d21ff_78011fb46df04467919927d36e936d16~mv2.jpg/v1/fill/w_2400,h_3600/temp%2049.JPG", "https://static.wixstatic.com/media/2d21ff_7b687e3bdc6340c4945019557e04fc76~mv2.jpg/v1/fill/w_2400,h_3600/temp%2048.JPG", "https://static.wixstatic.com/media/2d21ff_95fafe8e8dbc4aac86304017610b78f5~mv2.jpg/v1/fill/w_2400,h_3600/temp%2053.JPG", "https://static.wixstatic.com/media/2d21ff_1d1a2ea70aa942e696d78445b7fa2205~mv2.jpg/v1/fill/w_1312,h_2000/temp%2052.JPG", "https://static.wixstatic.com/media/2d21ff_c9f62e7ce9d14683a53e80d18ac0132f~mv2.jpg/v1/fill/w_1312,h_2000/temp%2051.JPG", "https://static.wixstatic.com/media/2d21ff_5ec150f232fb4154b57d45f407fcf72e~mv2.jpg/v1/fill/w_1312,h_2000/temp%2050.JPG"]}, {"title": "The Raf Simons Reset", "year_range": "2012 - 2015", "description": "Raf Simons stripped away Galliano''s excess, introducing minimalist modernity and architectural precision. His brief tenure modernized Dior''s codes with clean lines, innovative silhouettes, and a fresh, youthful energy that balanced heritage with contemporary edge.", "images": ["https://static.wixstatic.com/media/2d21ff_f57de79c87ec4947b6c67baa2223bb3a~mv2.jpg/v1/fill/w_683,h_1024/temp%2063.JPG", "https://static.wixstatic.com/media/2d21ff_17fcf0023e54416cb12a0454e712c028~mv2.jpg/v1/fill/w_683,h_1024/temp%2059.JPG", "https://static.wixstatic.com/media/2d21ff_d898c57802974b9c8b7e789505a592ce~mv2.jpg/v1/fill/w_683,h_1024/temp%2061.JPG", "https://static.wixstatic.com/media/2d21ff_3e4b89f7022f4ca0bc79fd4727e61de2~mv2.jpg/v1/fill/w_1366,h_2048/temp%2054.JPG", "https://static.wixstatic.com/media/2d21ff_7d5f1cd3cb8d45f483478db7e01b6d7b~mv2.jpg/v1/fill/w_1366,h_2048/temp%2056.JPG", "https://static.wixstatic.com/media/2d21ff_1e9c301a2c9f4976bf09c8c1776c9b30~mv2.jpg/v1/fill/w_1366,h_2048/temp%2057.JPG", "https://static.wixstatic.com/media/2d21ff_a193f3bc75c94a239c7fede2730673c2~mv2.jpg/v1/fill/w_1366,h_2048/temp%2055.JPG", "https://static.wixstatic.com/media/2d21ff_95a7a2555c5f4e5abb0b7f569598d5a4~mv2.jpg/v1/fill/w_1366,h_2048/temp%2062.JPG", "https://static.wixstatic.com/media/2d21ff_bec7ed662304429a84a24fd635637eba~mv2.jpg/v1/fill/w_1366,h_2048/temp%2060.JPG", "https://static.wixstatic.com/media/2d21ff_87dc830da1d3445690216fc00a0bf1fb~mv2.jpg/v1/fill/w_1366,h_2048/temp%2058.JPG"]}, {"title": "Feminist Couture", "year_range": "2016 - 2024", "description": "Maria Grazia Chiuri became Dior''s first female creative director, infusing the house with feminist messaging and empowered femininity. Her collections championed women''s voices through slogan tees, reimagined Bar jackets, and couture that celebrated strength and individuality.", "images": ["https://static.wixstatic.com/media/2d21ff_c689fcb08b6c45e2bf8db6a95a206e04~mv2.jpg/v1/fill/w_2000,h_3000/temp%2064.JPG", "https://static.wixstatic.com/media/2d21ff_3c40192dfbef4a6bb2ffef9e662cbd90~mv2.jpg/v1/fill/w_2000,h_3000/temp%2066.JPG", "https://static.wixstatic.com/media/2d21ff_dfb755c112fa4c47bef7fd5ec6a3589d~mv2.jpg/v1/fill/w_2000,h_3000/temp%2067.JPG", "https://static.wixstatic.com/media/2d21ff_22f16bb2d6d946dd8e5bf3ce3754a07a~mv2.jpg/v1/fill/w_2000,h_3000/temp%2068.JPG", "https://static.wixstatic.com/media/2d21ff_f45781a283554dfd8f2bd662dcf1de99~mv2.jpg/v1/fill/w_2000,h_3000/temp%2065.JPG", "https://static.wixstatic.com/media/2d21ff_c689fcb08b6c45e2bf8db6a95a206e04~mv2.jpg/v1/fill/w_2000,h_3000/temp%2064.JPG", "https://static.wixstatic.com/media/2d21ff_488bb44111d54df8ad16a8155a6364ab~mv2.jpg/v1/fill/w_2000,h_3000/temp%2069.JPG", "https://static.wixstatic.com/media/2d21ff_a7764f163ada4f4687b4b4c25f0b31d2~mv2.jpg/v1/fill/w_2000,h_3000/temp%2070.JPG", "https://static.wixstatic.com/media/2d21ff_79fe9fec0825401e9c316fd1dc6ba567~mv2.jpg/v1/fill/w_2732,h_4098/temp%2071.JPG", "https://static.wixstatic.com/media/2d21ff_b637581c4edd4ad981b5da27b9b7d9ab~mv2.jpg/v1/fill/w_2732,h_4098/temp%2072.JPG", "https://static.wixstatic.com/media/2d21ff_f46ba9b430d74e4d9bf304b38ff96971~mv2.jpg/v1/fill/w_2732,h_4098/temp%2074.JPG", "https://static.wixstatic.com/media/2d21ff_c9bb3c40e6a84255a0a6bd57efbbf6ba~mv2.jpg/v1/fill/w_2732,h_4098/temp%2073.JPG"]}, {"title": "A New Dior", "year_range": "2025 - Present", "description": "Under new creative direction, Dior enters an era of reinvention, balancing its storied heritage with bold, contemporary vision. This chapter is still unfolding, watch this space as the house writes its next iconic chapter.", "images": ["https://static.wixstatic.com/media/2d21ff_2ab7f8bf6ca641f7b5bca229e5d7ee4b~mv2.jpg/v1/fill/w_2732,h_4098/temp%2077.JPG", "https://static.wixstatic.com/media/2d21ff_18ceda7226ba4ad39418f1c62b1ff274~mv2.jpg/v1/fill/w_2732,h_4098/temp%2078.JPG", "https://static.wixstatic.com/media/2d21ff_216ad26a845245c3ae7b55430566176d~mv2.jpg/v1/fill/w_2732,h_4098/temp%2076.JPG", "https://static.wixstatic.com/media/2d21ff_38ae32b1bd364caeb04a0f1b4bd3e1d4~mv2.jpg/v1/fill/w_2732,h_4098/temp%2075.JPG"]}]',
