UPDATE designers SET
  name = 'Loewe',
  origin_location = 'Madrid, Spain',
  origin_meaning = 'Named after Enrique Loewe Roessberg, a German craftsman who settled in Madrid. The name is of German origin meaning ''lion''.',
  known_for_tags = '[{"name": "Craft driven", "description": ""}, {"name": "Artful", "description": ""}, {"name": "Conceptual", "description": ""}, {"name": "Sculptural", "description": ""}]',
  founder = 'Enrique Loewe Roessberg',
  signature_pieces = '[{"name": "Puzzle Bag", "image_url": "https://static.wixstatic.com/media/2d21ff_df044686bbe94b23b0b8c75e710eb0da~mv2.webp/v1/fill/w_1000,h_1334/30280287_59596866_1000.webp", "link": "https://www.farfetch.com/il/shopping/women/loewe-puzzle-geometric-leather-tote-bag-item-30280287.aspx"}, {"name": "Hammock Bag", "image_url": "https://static.wixstatic.com/media/2d21ff_5ec7dd46ec2b4355962254f22b13d079~mv2.webp/v1/fill/w_1000,h_1335/24385543_54411110_1000.webp", "link": "https://www.farfetch.com/il/shopping/women/loewe-hammock-tote-bag-item-24385543.aspx"}, {"name": "Flamenco Bag", "image_url": "https://static.wixstatic.com/media/2d21ff_6b24a9cad9ff41a38833f88940b0a481~mv2.webp/v1/fill/w_2048,h_2730/23747337_53744482_2048.webp", "link": "https://www.farfetch.com/il/shopping/women/loewe-flamenco-leather-shoulder-bag-item-23747337.aspx"}, {"name": "Draped leather tote bag", "image_url": "https://static.wixstatic.com/media/2d21ff_550912d37d454a9fb8af3c744ec342bd~mv2.webp/v1/fill/w_1000,h_1334/32699590_63118732_1000.webp", "link": "https://www.farfetch.com/sa/shopping/women/loewe-draped-leather-tote-bag-item-32699590.aspx"}, {"name": "90mm heel pumps", "image_url": "https://static.wixstatic.com/media/2d21ff_0041f0f4b63d4d02bb0991b8cee3c3dc~mv2.webp/v1/fill/w_1000,h_1334/30581253_61826430_1000.webp", "link": "https://www.farfetch.com/sa/shopping/women/loewe-90mm-ankle-strap-bulb-heel-pumps-item-30581253.aspx"}, {"name": "Belted leather jacket", "image_url": "https://static.wixstatic.com/media/2d21ff_6670eac8fc624fbd9e80b54b69379272~mv2.webp/v1/fill/w_1000,h_1334/31773001_61524170_1000.webp", "link": "https://www.farfetch.com/sa/shopping/women/loewe-belted-leather-jacket-item-31773001.aspx"}]',
  eras = '[{"title": "Pre-Reinvention Loewe", "year_range": "2000 - 2012", "description": "Before Jonathan Anderson''s arrival, Loewe navigated identity shifts under various creative directors, seeking its place in modern luxury while maintaining its leather craftsmanship heritage.", "images": ["https://static.wixstatic.com/media/2d21ff_17082c8d0cc4433a8b76aa2a5b76bc41~mv2.jpg/v1/fill/w_320,h_480/temp%205.JPG", "https://static.wixstatic.com/media/2d21ff_a5e36a6c893e4e81bc92b59a664475ca~mv2.jpg/v1/fill/w_320,h_480/temp%204.JPG", "https://static.wixstatic.com/media/2d21ff_ff3cdeec66d24e95b17099be55b12a0e~mv2.jpg/v1/fill/w_320,h_480/temp%202.JPG", "https://static.wixstatic.com/media/2d21ff_8b3e1b89bcff497eb87668bd1aa368db~mv2.jpg/v1/fill/w_683,h_1024/temp%208.JPG", "https://static.wixstatic.com/media/2d21ff_9a6a48e677084a24bb3b0bd96d47d8d4~mv2.jpg/v1/fill/w_683,h_1024/temp.JPG", "https://static.wixstatic.com/media/2d21ff_0bef571786ca46d183830551af23e181~mv2.jpg/v1/fill/w_683,h_1024/temp%2010.JPG", "https://static.wixstatic.com/media/2d21ff_a139321c304c485280a635fc438bf27c~mv2.jpg/v1/fill/w_683,h_1024/temp%2013.JPG", "https://static.wixstatic.com/media/2d21ff_0bef571786ca46d183830551af23e181~mv2.jpg/v1/fill/w_683,h_1024/temp%2010.JPG", "https://static.wixstatic.com/media/2d21ff_628f0024c3a345cfa4aeb1aa8a1a54ce~mv2.jpg/v1/fill/w_683,h_1024/temp%2011.JPG", "https://static.wixstatic.com/media/2d21ff_522d2abf172349e59de7b87a23d2c1ee~mv2.jpg/v1/fill/w_683,h_1024/temp%2012.JPG", "https://static.wixstatic.com/media/2d21ff_28663b720d314cbab517b0e812f4cdb8~mv2.jpg/v1/fill/w_683,h_1024/temp%209.JPG"]}, {"title": "Jonathan Anderson Arrives", "year_range": "2015", "description": "Anderson''s debut year signaled a radical departure, introducing surreal proportions, unexpected materials, and an art-forward sensibility that would redefine Loewe''s identity for the modern era.", "images": ["https://static.wixstatic.com/media/2d21ff_6c623102b5e9438b961335ecab0e146b~mv2.jpg/v1/fill/w_1366,h_2048/temp%2026.JPG", "https://static.wixstatic.com/media/2d21ff_e61685aa1ca749beb981755ee8b53d88~mv2.jpg/v1/fill/w_1366,h_2048/temp%2025.JPG", "https://static.wixstatic.com/media/2d21ff_d358636d968d4f578242b42e5f151d71~mv2.jpg/v1/fill/w_1366,h_2048/temp%2030.JPG", "https://static.wixstatic.com/media/2d21ff_edc5a2585d634334b230ca8f5f3b9053~mv2.jpg/v1/fill/w_1366,h_2048/temp%2027.JPG", "https://static.wixstatic.com/media/2d21ff_1d8ae04f61c24c5d978ae0ad47b5716e~mv2.jpg/v1/fill/w_1366,h_2048/temp%2029.JPG", "https://static.wixstatic.com/media/2d21ff_823bc25082a74effaf82807e3bd16626~mv2.jpg/v1/fill/w_1366,h_2048/temp%2028.JPG", "https://static.wixstatic.com/media/2d21ff_5ff8e7091bc54e069c3de44e7c2b0683~mv2.jpg/v1/fill/w_1366,h_2048/temp%2023.JPG", "https://static.wixstatic.com/media/2d21ff_0ded8807ad7a402c879e838706b7a72b~mv2.jpg/v1/fill/w_1366,h_2048/temp%2024.JPG"]}, {"title": "The New Loewe Language", "year_range": "2016 - 2018", "description": "Anderson solidified Loewe''s new codes with iconic bags like the Puzzle and Hammock, sculptural silhouettes, and collaborations with artists, establishing the house as a cultural force beyond fashion.", "images": ["https://static.wixstatic.com/media/2d21ff_57e1b0f3f19545a6a1e939a4f878b7e7~mv2.jpg/v1/fill/w_1366,h_2048/temp%2022.JPG", "https://static.wixstatic.com/media/2d21ff_0958c9671055495a8b551590800887e3~mv2.jpg/v1/fill/w_2000,h_3000/temp%2021.JPG", "https://static.wixstatic.com/media/2d21ff_d3dffd4b563042dc8234857dfe032a9b~mv2.jpg/v1/fill/w_2000,h_3000/temp%2018.JPG", "https://static.wixstatic.com/media/2d21ff_b2ab9d92574f4f6e9b92afcdca3c466d~mv2.jpg/v1/fill/w_1366,h_2048/temp%2019.JPG", "https://static.wixstatic.com/media/2d21ff_9816ff925ea34cbf8106d82a8fd292bd~mv2.jpg/v1/fill/w_1366,h_2048/temp%2020.JPG", "https://static.wixstatic.com/media/2d21ff_b8b737283cdf4119877a0930993070f1~mv2.jpg/v1/fill/w_2000,h_3000/temp%2017.JPG", "https://static.wixstatic.com/media/2d21ff_b8213222f65f4d7e909dc8d95556e7d2~mv2.jpg/v1/fill/w_2000,h_3000/temp%2016.JPG", "https://static.wixstatic.com/media/2d21ff_f7d72d44ad274dcea78ca604d38404d2~mv2.jpg/v1/fill/w_1366,h_2048/temp%2014.JPG", "https://static.wixstatic.com/media/2d21ff_796091f504124f9b8132f12a3c86f18e~mv2.jpg/v1/fill/w_1366,h_2048/temp%2015.JPG"]}, {"title": "Craft as Culture", "year_range": "2018 - Now", "description": "Loewe under Anderson reaches its mature phase, where craft, conceptual design, and cultural dialogue intertwine seamlessly, making the house a reference point for thoughtful, artful luxury.", "images": ["https://static.wixstatic.com/media/2d21ff_bc1274f09c274fb29ce658a463b93a4c~mv2.jpg/v1/fill/w_2732,h_4098/temp%2032.JPG", "https://static.wixstatic.com/media/2d21ff_3b0005ac359548afa044fdaa73b33569~mv2.jpg/v1/fill/w_2000,h_3000/temp%2038.JPG", "https://static.wixstatic.com/media/2d21ff_bffb7ce75c324ea39c6803025ce286c1~mv2.jpg/v1/fill/w_2732,h_4098/temp%2037.JPG", "https://static.wixstatic.com/media/2d21ff_c458bf186052438083e95d834d5febbe~mv2.jpg/v1/fill/w_2732,h_4098/temp%2034.JPG", "https://static.wixstatic.com/media/2d21ff_ffe1b58f0efa4c1c91f1e77c6ed51985~mv2.jpg/v1/fill/w_2732,h_4098/temp%2031.JPG", "https://static.wixstatic.com/media/2d21ff_77bc893539e9423288f5733f73505693~mv2.jpg/v1/fill/w_2732,h_4098/temp%2033.JPG", "https://static.wixstatic.com/media/2d21ff_f7ddb4acfed94a389239d0941a89b7a2~mv2.jpg/v1/fill/w_2732,h_4098/temp%2035.JPG", "https://static.wixstatic.com/media/2d21ff_56b10789b8d344bcb37830b836cef4c4~mv2.jpg/v1/fill/w_2000,h_3000/temp%2036.JPG", "https://static.wixstatic.com/media/2d21ff_aed2a3f462734dfab501c22622442f1b~mv2.jpg/v1/fill/w_2732,h_4098/temp%2039.JPG", "https://static.wixstatic.com/media/2d21ff_25d08a0677ef4497863731b932d25d9f~mv2.jpg/v1/fill/w_2732,h_4098/temp%2041.JPG", "https://static.wixstatic.com/media/2d21ff_7c1ad030fec142fdad39a4bb038bc2cc~mv2.jpg/v1/fill/w_2732,h_4098/temp%2040.JPG", "https://static.wixstatic.com/media/2d21ff_d7129cc61fb74f70ada4ada300854d6c~mv2.jpg/v1/fill/w_2000,h_3000/temp%2042.JPG"]}]',
